 void refreshBranch(){if(branchToggle==null)return;refreshingBranch=true;int n=Store.count(Store.selected(this),branchId),total=Catalog.leaves(branchId).size();branchToggle.setText((n>0&&n<total?"Частично выбрано · ":"Всё направление · ")+n+"/"+total);branchToggle.setChecked(n==total);refreshingBranch=false;}
 void topic(String id){Catalog.Topic t=Catalog.index.get(id);if(t==null){show("topics");return;}body.addView(button("← Назад",()->show(Catalog.parent(id))));body.addView(text(t.title,28,TEXT));body.addView(text("Выберите всё направление или отдельные подтемы. Изменения появятся в общей ленте без повторов.",15,MUTED));
 Switch all=new Switch(this);int selected=Store.count(Store.selected(this),id),total=Catalog.leaves(id).size();all.setText("Всё направление · "+selected+"/"+total);all.setTextColor(TEXT);all.setTextSize(17);all.setPadding(dp(12),dp(16),dp(12),dp(16));all.setChecked(selected==total);branchId=id;branchToggle=all;all.setOnCheckedChangeListener((b,on)->{if(refreshingBranch)return;Store.toggle(this,id,on);show("topic:"+id);});body.addView(all);
 for(Catalog.Topic child:t.children)topicRow(child);refreshBranch();
 if(id.startsWith("health"))body.addView(text("Здесь отслеживаются правила оказания помощи, права пациентов и обеспечение. Это не подбор лечения и не лента медицинских исследований.",14,MUTED));
 TextView link=text("Источники направления  ↗",13,MUTED);link.setMinHeight(dp(48));link.setGravity(Gravity.END);link.setFocusable(true);link.setOnClickListener(v->show("source:"+id));body.addView(link);
 }
 void sources(){body.addView(button("← К настройкам",()->show("settings")));body.addView(text("Официальные источники",28,TEXT));body.addView(text("Автозагрузка документов и проверка выжимок — разные этапы. Документ без проверенной выжимки не попадает в уведомления.",16,MUTED));
 String filter=screen.startsWith("source:")?screen.substring(7):"";if(!filter.isEmpty())body.addView(button("← К подтемам",()->show("topic:"+filter)));
 try {JSONObject data=new JSONObject(Store.feed(this));Map<String,JSONObject> status=new HashMap<>();JSONArray states=data.optJSONArray("sources");if(states!=null)for(int i=0;i<states.length();i++)status.put(states.getJSONObject(i).getString("id"),states.getJSONObject(i));
 java.io.InputStream in=getAssets().open("official-sources.json");java.io.ByteArrayOutputStream buffer=new java.io.ByteArrayOutputStream();byte[] bytes=new byte[8192];int len;while((len=in.read(bytes))!=-1)buffer.write(bytes,0,len);in.close();JSONArray directory=new JSONArray(buffer.toString("UTF-8"));
 for(int i=0;i<directory.length();i++){JSONObject source=directory.getJSONObject(i);JSONArray categories=source.getJSONArray("categories");boolean match=filter.isEmpty()||Catalog.sourcesFor(filter).contains(source.getString("id"));if(!match)continue;LinearLayout c=card();c.addView(text(source.getString("title"),20,TEXT));JSONObject state=status.get(source.getString("id"));String note="Официальная ссылка. Автозагрузка не подключена.";if(state!=null){String kind=state.optString("status");note=kind.equals("ok")?"Автозагрузка документов: работает. Последняя успешная загрузка: "+state.optString("fetchedAt"):kind.equals("snapshot")?"Есть проверенная архивная карточка. Автозагрузка ограничена.":"Автозагрузка пока недоступна.";if(!state.optString("message").isEmpty())note+="\n"+state.optString("message");}c.addView(text(note,14,MUTED));c.addView(button("Открыть официальный сайт ↗",()->open(source.optString("url"))));body.addView(c);}
 JSONArray pending=data.optJSONArray("pending");if(pending!=null&&pending.length()>0){body.addView(text("Документы на проверке",22,TEXT));body.addView(text("Это официально опубликованные акты. Выжимки и окончательная привязка к подтемам ещё не проверены; уведомлений по ним нет.",14,MUTED));int shown=0;for(int i=0;i<pending.length()&&shown<8;i++){JSONObject item=pending.getJSONObject(i);if(!filter.isEmpty()&&!Catalog.rootId(filter).equals(item.optString("categoryId")))continue;String url=item.optString("sourceUrl");if(!url.matches("https://www\\.cbr\\.ru/Queries/UniDbQuery/File/90134/[0-9]+")&&!url.matches("https://www\\.nalog\\.gov\\.ru/rn[0-9]+/about_fts/docs/[0-9]+/"))continue;shown++;LinearLayout c=card();c.addView(text(item.optString("title"),16,TEXT));c.addView(text("Опубликовано: "+item.optString("publishedAt"),12,MUTED));c.addView(button("Документ без выжимки ↗",()->open(url)));body.addView(c);}}
 }catch(Exception e){body.addView(text("Сведения об источниках временно недоступны",16,MUTED));}}
 void open(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){Toast.makeText(this,"На телефоне нет браузера для этой ссылки",Toast.LENGTH_LONG).show();}}
 class RadarView extends View {
 Paint paint=new Paint(3);RadarView(Context c){super(c);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}
 @Override public boolean onTouchEvent(MotionEvent event){if(!isClickable())return super.onTouchEvent(event);if(event.getAction()==MotionEvent.ACTION_DOWN)return true;if(event.getAction()==MotionEvent.ACTION_UP){float x=getWidth()/2f,y=getHeight()/2f,r=Math.min(x,y)*.76f;for(int i=0;i<8;i++){double angle=-Math.PI/2+i*Math.PI/4;float nx=x+(float)Math.cos(angle)*r*.88f,ny=y+(float)Math.sin(angle)*r*.88f;if(Math.hypot(event.getX()-nx,event.getY()-ny)<dp(25)){show("topic:"+Feed.IDS[i]);return true;}}performClick();return true;}return true;}
 @Override public boolean performClick(){return super.performClick();}
 protected void onDraw(Canvas c){float x=getWidth()/2f,y=getHeight()/2f,r=Math.min(x,y)*.76f;paint.setShader(new RadialGradient(x-r/3,y-r/3,r*1.6f,lightTheme?new int[]{Color.WHITE,BG,Color.rgb(218,232,241)}:new int[]{Color.rgb(38,44,48),BG,Color.rgb(25,30,33)},null,Shader.TileMode.CLAMP));paint.setStyle(Paint.Style.FILL);c.drawCircle(x,y,r,paint);paint.setShader(null);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(1));paint.setColor(lightTheme?Color.rgb(198,213,224):Color.rgb(47,57,63));c.drawCircle(x,y,r,paint);for(int i=1;i<=3;i++)c.drawCircle(x,y,r*i/4,paint);String[] labels={"Здоровье","Выплаты","Жильё","Работа","Семья","Учёба","Налоги","Покупки"};
 Set<String> enabled=Store.enabled(MainActivity.this);
 for(int i=0;i<8;i++){double angle=-Math.PI/2+i*Math.PI/4;float nx=x+(float)Math.cos(angle)*r*.88f,ny=y+(float)Math.sin(angle)*r*.88f;boolean on=enabled.contains(Feed.IDS[i]);int color=on?(Feed.IDS[i].equals("health")?(lightTheme?Color.rgb(36,116,59):Color.rgb(127,227,145)):Feed.IDS[i].equals("tax")||Feed.IDS[i].equals("benefits")?(lightTheme?Color.rgb(139,87,0):Color.rgb(245,194,93)):CYAN):(lightTheme?Color.rgb(148,164,176):Color.rgb(54,64,72));paint.setColor(color);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(on?1.2f:.6f));paint.setShadowLayer(dp(on?5:0),0,0,color);Path ray=new Path();ray.moveTo(x,y);ray.cubicTo(x+(nx-x)*.6f,y, nx,ny+(y-ny)*.25f,nx,ny);c.drawPath(ray,paint);paint.setStyle(Paint.Style.FILL);c.drawCircle(nx,ny,dp(on?4:2),paint);paint.clearShadowLayer();paint.setTextSize(dp(11));paint.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));paint.setTextAlign(Paint.Align.CENTER);float ty=ny+(Math.sin(angle)>.3?dp(20):-dp(12));c.drawText(labels[i],nx,ty,paint);}
 paint.setColor(TEXT);paint.setShadowLayer(dp(12),0,0,CYAN);paint.setStyle(Paint.Style.FILL);c.drawCircle(x,y,dp(7),paint);paint.clearShadowLayer();paint.setColor(CYAN);paint.setStyle(Paint.Style.STROKE);c.drawCircle(x,y,dp(13),paint);}
 }
